            solve_panel_16(tile, panel);
            compensated_rankk_16(tile, panel);
        }
    }

    for (int vector = tid; vector < N * N / 4;
         vector += blockDim.x) {
        const int row = vector / (N / 4);
        const int col = vector % (N / 4) * 4;
        float4 values = reinterpret_cast<const float4*>(tile)[vector];
        if (row < col + 3) values.w = 0.0f;
